import {createGame,registerAgent,startRound,stepDemo,PRODUCTS,PERSONALITIES,money} from './engine.js';

let state=createGame(),selected='atlas',running=false,busy=false,timer=null,speed=1000,filter='all',notice='',local=false,mode='demo';
const $=selector=>document.querySelector(selector);
const esc=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const total=key=>state.agents.reduce((sum,agent)=>sum+agent[key],0);
const joined=()=>state.agents.filter(agent=>agent.registered).length;

function chart(){
  if(state.history.length<2)return '<div class="chart-empty">The round begins when all four agents register.<p>Cash trajectories appear after the first market day.</p></div>';
  const values=state.history.flatMap(point=>point.cash),low=Math.min(0,...values),high=Math.max(60000,...values)*1.08;
  const y=value=>180-(value-low)/(high-low)*165,x=day=>45+day/Math.max(1,state.day)*665;
  return `<svg class="chart" viewBox="0 0 720 195" role="img" aria-label="Bank balance during the round for each agent">${[0,.5,1].map(fraction=>{const value=low+fraction*(high-low);return `<line x1="45" x2="710" y1="${y(value)}" y2="${y(value)}" stroke="#30392e" stroke-dasharray="3 5"/><text x="0" y="${y(value)+3}" fill="#8e9d8c" font-size="9">$${Math.round(value/100)}</text>`;}).join('')}${state.agents.map((agent,index)=>`<polyline points="${state.history.map(point=>`${x(point.day)},${y(point.cash[index])}`).join(' ')}" fill="none" stroke="${agent.color}" stroke-width="2" stroke-linejoin="round"/>`).join('')}</svg><div class="chart-labels"><span>OPEN</span><span>DAY ${state.day}</span></div>`;
}

function lobby(){
  const waiting=state.requiredAgents-joined();
  return `<section class="lobby panel"><div class="lobby-title"><div><div class="eyebrow">Round ${String(state.round).padStart(2,'0')} · Registration</div><h2>Waiting for ${waiting} agent${waiting===1?'':'s'}</h2><p>The round unlocks when every machine owner registers with at least ${money(state.minimumEntry)}.</p></div><div class="wallet"><span class="eyebrow">Customer wallet forming</span><strong class="mono">${money(state.customerBudgetTotal)}</strong><small>${joined()} of ${state.requiredAgents} balances mirrored</small></div></div>
  <div class="lobby-settings"><label>Market seed<input id="seed" type="number" min="0" max="4294967295" value="${state.seed}" ${joined()?'disabled':''}></label><label>Start date<input id="start-date" type="date" value="${state.startDate}" ${joined()?'disabled':''}></label><label>Agent engine<select id="mode" ${joined()?'disabled':''}><option value="demo" ${mode==='demo'?'selected':''}>Built-in strategies</option><option value="codex" ${mode==='codex'?'selected':''} ${local?'':'disabled'}>Codex agents${local?'':' · local runner required'}</option></select></label></div>
  <div class="signup-grid">${state.agents.map((agent,index)=>`<article class="signup ${agent.registered?'joined':''}" style="--accent:${agent.color}"><div><span class="agent-index">SLOT 0${index+1}</span><h3>${agent.name}</h3><p>${agent.strategy} starting hypothesis</p></div>${agent.registered?`<div class="joined-mark">✓ Registered<br><strong class="mono">${money(agent.entryBalance)}</strong></div>`:`<label>Starting balance<input data-balance="${agent.id}" type="number" min="${state.minimumEntry/100}" step="1" value="${state.minimumEntry/100}"></label><button class="button" data-signup="${agent.id}" ${busy?'disabled':''}>Sign up</button>`}</article>`).join('')}</div>
  <div class="lobby-actions"><button class="button" id="register-all" ${busy||joined()===state.requiredAgents?'disabled':''}>Register remaining at ${money(state.minimumEntry)}</button><button class="button primary" id="start-round" ${busy||joined()!==state.requiredAgents?'disabled':''}>Open the market →</button></div>
  <p class="help">Registration balances remain working capital and are mirrored into one finite customer wallet. Four agents at the minimum create ${money(state.minimumEntry*state.requiredAgents)} of customer demand.</p></section>`;
}

function arena(){
  const agent=state.agents.find(item=>item.id===selected),ranking=[...state.agents].sort((a,b)=>b.cash-a.cash),logs=state.log.filter(event=>filter==='all'||event.agent===filter).slice(-80).reverse();
  const progress=state.customerBudgetTotal?state.customerBudgetSpent/state.customerBudgetTotal*100:0;
  return `<div class="controls"><button class="button primary" id="play" ${(busy&&!running)||state.phase==='finished'?'disabled':''}>${running?'Ⅱ Pause round':'▶ Run round'}</button><button class="button" id="step" ${busy||running||state.phase==='finished'?'disabled':''}>Next day →</button><label>Speed<select id="speed"><option value="1000" ${speed===1000?'selected':''}>1×</option><option value="350" ${speed===350?'selected':''}>3×</option><option value="80" ${speed===80?'selected':''}>10×</option></select></label><span class="spacer"></span><span class="status" role="status">${busy?'Agents are deciding…':state.phase==='finished'?'Round complete':running?'Market is running':'Market is paused'}</span><button class="button" id="new">New round</button></div>
  <div class="progress" aria-label="Customer budget spent"><span style="width:${progress}%"></span></div>
  <section class="arena"><div class="arena-top"><div class="place">◉ Mission Bay Plaza <span>Round ${String(state.round).padStart(2,'0')} · Shared customer wallet</span></div><div class="market"><span>${state.weather==='Hot'?'☀':state.weather==='Rainy'?'☂':'◌'} ${state.weather}</span><span>${state.unitsSoldToday} units sold today</span><span class="mono">DAY ${String(state.day).padStart(3,'0')}</span></div></div>
  <div class="agents">${state.agents.map((item,index)=>`<button class="agent ${selected===item.id?'selected':''}" data-agent="${item.id}" style="--accent:${item.color}" aria-pressed="${selected===item.id}" aria-label="Inspect ${item.name}"><div class="agent-title"><span class="agent-name">${item.name}</span><span class="agent-index">0${index+1} ↗</span></div><span class="tag">${mode==='codex'?'CODEX AGENT':item.strategy.toUpperCase()+' POLICY'}${!item.active?' · CLOSED':''}</span><div class="stock-preview">${PRODUCTS.map(product=>`<div class="stock-cell"><span class="icon" aria-hidden="true">${product.icon}</span><small>${item.inventory[product.id]} / 30</small></div>`).join('')}</div><div class="agent-bottom"><div><div class="small-label">Bank balance</div><div class="cash mono">${money(item.cash)}</div></div><div class="delta mono">${item.cash>=item.entryBalance?'+':''}${((item.cash/item.entryBalance-1)*100).toFixed(1)}%</div></div></button>`).join('')}</div>
  <div class="arena-footer"><span>SELECT A MACHINE TO INSPECT ITS BUSINESS</span><span>${state.calendar.date} · ${money(state.customerBudgetRemaining)} left to win</span></div></section>
  <div class="metric-row"><div class="metric"><div class="eyebrow">Customer wallet</div><strong class="mono">${money(state.customerBudgetRemaining)}</strong><small>of ${money(state.customerBudgetTotal)} remaining</small></div><div class="metric"><div class="eyebrow">Captured revenue</div><strong class="mono">${money(state.customerBudgetSpent)}</strong><small>${progress.toFixed(1)}% of the wallet spent</small></div><div class="metric"><div class="eyebrow">Items sold</div><strong class="mono">${total('sold').toLocaleString()}</strong><small>Across all four machines</small></div><div class="metric"><div class="eyebrow">Market leader</div><strong>${state.day===0?'Undecided':ranking[0].name}</strong><small>${money(ranking[0].cash)} bank balance</small></div></div>
  ${state.phase==='finished'?`<div class="round-result"><div class="eyebrow">Round ${String(state.round).padStart(2,'0')} complete</div><h2>${ranking[0].name} wins with ${money(ranking[0].cash)}</h2><p>${state.finishReason==='customer_budget_exhausted'?`The agents captured the entire ${money(state.customerBudgetTotal)} customer wallet.`:`All machines closed before the final ${money(state.customerBudgetRemaining)} could be spent.`}${state.closingAdjustment?` The closing purchase used ${money(state.closingAdjustment)} less than its listed price to empty the wallet exactly.`:''}</p></div>`:''}
  <div class="grid"><section class="panel"><div class="panel-head"><h2>The long game</h2><div class="legend">${state.agents.map(item=>`<span><i style="background:${item.color}"></i>${item.name}</span>`).join('')}</div></div><p class="help">Agent bank balances · USD</p>${chart()}</section><section class="panel"><div class="panel-head"><h2>Leaderboard</h2><span class="eyebrow">By bank balance</span></div>${ranking.map((item,index)=>`<div class="rank-row"><span class="rank-number">0${index+1}</span><div class="rank-name">${item.name} <span style="color:var(--muted);font-size:10px">/ ${mode==='codex'?'Codex':item.strategy}</span><div class="rank-bar"><span style="width:${Math.max(0,item.cash/Math.max(1,ranking[0].cash)*100)}%;background:${item.color}"></span></div></div><span class="rank-cash mono">${money(item.cash)}</span></div>`).join('')}</section></div>
  <section class="panel detail"><div class="panel-head"><h2><span style="color:${agent.color}">◉</span> Inside ${agent.name}’s business</h2><span class="tag" style="--accent:${agent.color}">${agent.active?'OPERATING':'CLOSED'}</span></div><div class="detail-grid"><div><div class="eyebrow">Latest decision</div><div class="quote">“${esc(agent.rationale)}”</div><div class="eyebrow" style="margin-bottom:10px">Agent notebook</div><div class="note">${esc(agent.memory||'No decisions yet. Open the market to begin.')}</div><p class="help">Entered with ${money(agent.entryBalance)} · ${agent.orders.length} deliveries pending · ${money(agent.spending)} stock purchased · ${money(agent.fees)} rent paid</p></div><div><table><thead><tr><th>Product</th><th>Price</th><th>Machine</th><th>Storage</th><th>Sold today</th></tr></thead><tbody>${PRODUCTS.map(product=>`<tr><td>${product.icon} ${product.name}</td><td class="mono">${money(agent.prices[product.id])}</td><td>${agent.inventory[product.id]}/30</td><td>${agent.storage[product.id]}</td><td>${agent.lastSales[product.id]}</td></tr>`).join('')}</tbody></table></div></div></section>
  <section class="panel" style="margin-top:22px"><div class="panel-head"><h2>How sales are calculated</h2><span class="eyebrow">Finite wallet · paper-based demand</span></div><p>Daily demand follows <a href="https://arxiv.org/html/2502.15840v1#S2.SS2.SSS2" target="_blank" rel="noreferrer">Vending-Bench §2.2.2</a>. Completed purchases drain the shared customer wallet.</p>${state.salesReport.length?`<table><thead><tr><th>Product</th><th>Expected units</th><th>After noise</th><th>Units sold</th></tr></thead><tbody>${state.salesReport.map(report=>`<tr><td>${PRODUCTS.find(product=>product.id===report.product).name}</td><td>${report.expected.toFixed(1)}</td><td>${report.demand}</td><td>${report.sold}</td></tr>`).join('')}</tbody></table>`:''}</section>
  <section class="panel feed"><div class="panel-head"><h2>Life in the market</h2><label><span class="sr-only">Filter activity by agent</span><select id="filter"><option value="all">All activity</option>${PERSONALITIES.map(item=>`<option value="${item.id}" ${filter===item.id?'selected':''}>${item.name}</option>`).join('')}</select></label></div><div class="feed-list">${logs.map(event=>`<div class="feed-item"><span class="feed-day">D${String(event.day).padStart(3,'0')}</span><span style="color:${PERSONALITIES.find(item=>item.id===event.agent)?.color||'#8e9d8c'}">${PERSONALITIES.find(item=>item.id===event.agent)?.name||'Market'}</span><span class="feed-text">${esc(event.text)}</span></div>`).join('')}</div></section>
  <section class="panel" style="margin-top:22px"><div class="panel-head"><h2>Agent engine</h2><span class="tag">${mode==='codex'?'CODEX AGENTS':'BUILT-IN STRATEGIES'}</span></div><p>${mode==='demo'?'Four transparent strategies make the business decisions.':'Four local Codex agents choose prices, loading and orders from private notebooks and the shared wallet state.'}</p><button class="button" id="export">↓ Export round JSON</button></section>`;
}

function render(){
  $('#app').innerHTML=`<header><div class="brand"><span class="brand-mark">va.</span> vending arena</div><div class="header-right"><span><i class="live-dot"></i>FINITE-MARKET COMPETITION</span><a href="https://andonlabs.com/evals/vending-bench-2" target="_blank" rel="noreferrer">The inspiration ↗</a></div></header><main><div class="intro"><div><div class="eyebrow">Four agents. One wallet. One winner.</div><h1>Enter the market.<br><em>Capture the budget.</em></h1><p>Agents register capital, run their own machines, and compete until customer money is gone.</p></div><div class="season-pill mono">ROUND ${String(state.round).padStart(2,'0')} <span style="color:var(--muted)">/ SEED ${state.seed}</span></div></div>${notice?`<div class="notice" role="alert">${esc(notice)}</div>`:''}${state.phase==='lobby'?lobby():arena()}<footer><span>VENDING ARENA · FINITE CUSTOMER WALLET</span><span>Same market. Different decisions. Simulated money.</span></footer></main>`;
  bind();
}

function bind(){
  if(state.phase==='lobby'){
    document.querySelectorAll('[data-signup]').forEach(button=>button.onclick=()=>signup(button.dataset.signup));
    $('#register-all').onclick=async()=>{for(const agent of state.agents.filter(item=>!item.registered)){await signup(agent.id,true);if(notice)break;}render();};
    $('#start-round').onclick=openMarket;
    $('#mode').onchange=event=>reset({seed:state.seed,startDate:state.startDate},event.target.value);
    for(const id of ['seed','start-date'])$(`#${id}`).onchange=()=>reset({seed:Number($('#seed').value),startDate:$('#start-date').value},mode);
    return;
  }
  $('#play').onclick=()=>{running=!running;render();schedule();};$('#step').onclick=advance;
  $('#speed').onchange=event=>{speed=Number(event.target.value);schedule();};
  $('#new').onclick=()=>reset({seed:state.seed,startDate:state.startDate},mode);
  document.querySelectorAll('[data-agent]').forEach(button=>button.onclick=()=>{selected=button.dataset.agent;render();});
  $('#filter').onchange=event=>{filter=event.target.value;render();};
  $('#export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const anchor=document.createElement('a');anchor.href=url;anchor.download=`vending-arena-round-${state.round}-seed-${state.seed}.json`;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
}

function schedule(){clearTimeout(timer);if(running&&!busy&&state.phase!=='finished')timer=setTimeout(advance,speed);}
async function request(path,body){const response=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok)throw new Error(data.error||'The local runner could not complete the request.');if(data.version&&data.version!==3)throw new Error('Restart the local server to use the round-based game.');return data;}
async function reset(options,nextMode=mode){running=false;clearTimeout(timer);busy=true;try{state=nextMode==='codex'?await request('/api/reset',{...options,mode:nextMode}):createGame({...options,mode:nextMode});mode=nextMode;notice='';}catch(error){notice=error.message;}finally{busy=false;render();}}
async function signup(id,silent=false){if(busy)return;busy=true;if(!silent)render();try{const input=document.querySelector(`[data-balance="${id}"]`),balance=Math.round(Number(input?.value??state.minimumEntry/100)*100);state=mode==='codex'?await request('/api/register',{id,balance}):registerAgent(state,id,balance);notice='';}catch(error){notice=error.message;}finally{busy=false;if(!silent)render();}}
async function openMarket(){busy=true;render();try{state=mode==='codex'?await request('/api/start',{}):startRound(state);notice='';}catch(error){notice=error.message;}finally{busy=false;render();}}
async function advance(){if(busy||state.phase==='finished')return;busy=true;render();try{state=mode==='codex'?await request('/api/step',{}):stepDemo(state);notice='';}catch(error){notice=error.message;running=false;}finally{busy=false;if(state.phase==='finished')running=false;render();schedule();}}

render();
if(['localhost','127.0.0.1','[::1]'].includes(location.hostname))fetch('/api/status').then(response=>response.ok?response.json():null).then(data=>{local=data?.local===true;render();}).catch(()=>{});
if(document.modelContext?.registerTool){
  const lifecycle=new AbortController(),register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
  register({name:'read_vending_arena',description:'Read the lobby or current round, including registrations, customer wallet, agent balances, stock and public events.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>structuredClone(state)});
  addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
